  2	  This is just a junk drawer, containing anything used across multiple classes.
  3	  Because Luxon is small(ish), this should stay small and we won't worry about splitting
  4	  it up into, say, parsingUtil.js and basicUtil.js and so on. But they are divided up by feature area.
  5	*/
  6	
  7	import { InvalidArgumentError } from "../errors.js";
  8	
  9	/**
 10	 * @private
 11	 */
 12	
 13	// TYPES
 14	
 15	export function isUndefined(o) {
 16	  return typeof o === "undefined";
 17	}
 18	
 19	export function isNumber(o) {
 20	  return typeof o === "number";
 21	}
 22	
 23	export function isInteger(o) {
 24	  return typeof o === "number" && o % 1 === 0;
 25	}
 26	
 27	export function isString(o) {
 28	  return typeof o === "string";
 29	}
 30	
 31	export function isDate(o) {
 32	  return Object.prototype.toString.call(o) === "[object Date]";
 33	}
 34	
 35	// CAPABILITIES
 36	
 37	export function hasIntl() {
 38	  try {
 39	    return typeof Intl !== "undefined" && Intl.DateTimeFormat;
 40	  } catch (e) {
 41	    return false;
 42	  }
 43	}
 44	
 45	export function hasFormatToParts() {
 46	  return !isUndefined(Intl.DateTimeFormat.prototype.formatToParts);
 47	}
 48	
 49	export function hasRelative() {
 50	  try {
 51	    return typeof Intl !== "undefined" && !!Intl.RelativeTimeFormat;
 52	  } catch (e) {
 53	    return false;
 54	  }
 55	}
 56	
 57	// OBJECTS AND ARRAYS
 58	
 59	export function maybeArray(thing) {
 60	  return Array.isArray(thing) ? thing : [thing];
 61	}
 62	
 63	export function bestBy(arr, by, compare) {
 64	  if (arr.length === 0) {
 65	    return undefined;
 66	  }
 67	  return arr.reduce((best, next) => {
 68	    const pair = [by(next), next];
 69	    if (!best) {
 70	      return pair;
 71	    } else if (compare(best[0], pair[0]) === best[0]) {
 72	      return best;
 73	    } else {
 74	      return pair;
 75	    }
 76	  }, null)[1];
 77	}
 78	
 79	export function pick(obj, keys) {
 80	  return keys.reduce((a, k) => {
 81	    a[k] = obj[k];
 82	    return a;
 83	  }, {});
 84	}
 85	
 86	export function hasOwnProperty(obj, prop) {
 87	  return Object.prototype.hasOwnProperty.call(obj, prop);
 88	}
 89	
 90	// NUMBERS AND STRINGS
 91	
 92	export function integerBetween(thing, bottom, top) {
 93	  return isInteger(thing) && thing >= bottom && thing <= top;
 94	}
 95	
 96	// x % n but takes the sign of n instead of x
 97	export function floorMod(x, n) {
 98	  return x - n * Math.floor(x / n);
 99	}
100	
101	export function padStart(input, n = 2) {
102	  if (input.toString().length < n) {
103	    return ("0".repeat(n) + input).slice(-n);
104	  } else {
105	    return input.toString();
106	  }
107	}
108	
109	export function parseInteger(string) {
110	  if (isUndefined(string) || string === null || string === "") {
111	    return undefined;
112	  } else {
113	    return parseInt(string, 10);
114	  }
115	}
116	
117	export function parseMillis(fraction) {
118	  // Return undefined (instead of 0) in these cases, where fraction is not set
119	  if (isUndefined(fraction) || fraction === null || fraction === "") {
120	    return undefined;
121	  } else {
122	    const f = parseFloat("0." + fraction) * 1000;
123	    return Math.floor(f);
124	  }
125	}
126	
127	export function roundTo(number, digits, towardZero = false) {
128	  const factor = 10 ** digits,
129	    rounder = towardZero ? Math.trunc : Math.round;
130	  return rounder(number * factor) / factor;
131	}
132	
133	// DATE BASICS
134	
135	export function isLeapYear(year) {
136	  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
137	}
138	
139	export function daysInYear(year) {
140	  return isLeapYear(year) ? 366 : 365;
141	}
142	
143	export function daysInMonth(year, month) {
144	  const modMonth = floorMod(month - 1, 12) + 1,
145	    modYear = year + (month - modMonth) / 12;
146	
147	  if (modMonth === 2) {
148	    return isLeapYear(modYear) ? 29 : 28;
149	  } else {
150	    return [31, null, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][modMonth - 1];
151	  }
152	}
153	
154	// covert a calendar object to a local timestamp (epoch, but with the offset baked in)
155	export function objToLocalTS(obj) {
156	  let d = Date.UTC(
157	    obj.year,
158	    obj.month - 1,
159	    obj.day,
160	    obj.hour,
161	    obj.minute,
162	    obj.second,
163	    obj.millisecond
164	  );
165	
166	  // for legacy reasons, years between 0 and 99 are interpreted as 19XX; revert that
167	  if (obj.year < 100 && obj.year >= 0) {
168	    d = new Date(d);
169	    d.setUTCFullYear(d.getUTCFullYear() - 1900);
170	  }
171	  return +d;
172	}
173	
174	export function weeksInWeekYear(weekYear) {
175	  const p1 =
176	      (weekYear +
177	        Math.floor(weekYear / 4) -
178	        Math.floor(weekYear / 100) +
179	        Math.floor(weekYear / 400)) %
180	      7,
181	    last = weekYear - 1,
182	    p2 = (last + Math.floor(last / 4) - Math.floor(last / 100) + Math.floor(last / 400)) % 7;
183	  return p1 === 4 || p2 === 3 ? 53 : 52;
184	}
185	
186	export function untruncateYear(year) {
187	  if (year > 99) {
188	    return year;
189	  } else return year > 60 ? 1900 + year : 2000 + year;
190	}
191	
192	// PARSING
193	
194	export function parseZoneInfo(ts, offsetFormat, locale, timeZone = null) {
195	  const date = new Date(ts),
196	    intlOpts = {
197	      hour12: false,
198	      year: "numeric",
199	      month: "2-digit",
200	      day: "2-digit",
201	      hour: "2-digit",
202	      minute: "2-digit"
203	    };
204	
205	  if (timeZone) {
206	    intlOpts.timeZone = timeZone;
207	  }
208	
209	  const modified = Object.assign({ timeZoneName: offsetFormat }, intlOpts),
210	    intl = hasIntl();
211	
212	  if (intl && hasFormatToParts()) {
213	    const parsed = new Intl.DateTimeFormat(locale, modified)
214	      .formatToParts(date)
215	      .find(m => m.type.toLowerCase() === "timezonename");
216	    return parsed ? parsed.value : null;
217	  } else if (intl) {
218	    // this probably doesn't work for all locales
219	    const without = new Intl.DateTimeFormat(locale, intlOpts).format(date),
220	      included = new Intl.DateTimeFormat(locale, modified).format(date),
221	      diffed = included.substring(without.length),
222	      trimmed = diffed.replace(/^[, \u200e]+/, "");
223	    return trimmed;
224	  } else {
225	    return null;
226	  }
227	}
