229	// signedOffset('-5', '30') -> -330
230	export function signedOffset(offHourStr, offMinuteStr) {
231	  let offHour = parseInt(offHourStr, 10);
232	
233	  // don't || this because we want to preserve -0
234	  if (Number.isNaN(offHour)) {
235	    offHour = 0;
236	  }
237	
238	  const offMin = parseInt(offMinuteStr, 10) || 0,
239	    offMinSigned = offHour < 0 || Object.is(offHour, -0) ? -offMin : offMin;
240	  return offHour * 60 + offMinSigned;
241	}
242	
243	// COERCION
244	
245	export function asNumber(value) {
246	  const numericValue = Number(value);
247	  if (typeof value === "boolean" || value === "" || Number.isNaN(numericValue))
248	    throw new InvalidArgumentError(`Invalid unit value ${value}`);
249	  return numericValue;
250	}
251	
252	export function normalizeObject(obj, normalizer, nonUnitKeys) {
253	  const normalized = {};
254	  for (const u in obj) {
255	    if (hasOwnProperty(obj, u)) {
256	      if (nonUnitKeys.indexOf(u) >= 0) continue;
257	      const v = obj[u];
258	      if (v === undefined || v === null) continue;
259	      normalized[normalizer(u)] = asNumber(v);
260	    }
261	  }
262	  return normalized;
263	}
264	
265	export function formatOffset(offset, format) {
266	  const hours = Math.trunc(offset / 60),
267	    minutes = Math.abs(offset % 60),
268	    sign = hours >= 0 && !Object.is(hours, -0) ? "+" : "-",
269	    base = `${sign}${Math.abs(hours)}`;
270	
271	  switch (format) {
272	    case "short":
273	      return `${sign}${padStart(Math.abs(hours), 2)}:${padStart(minutes, 2)}`;
274	    case "narrow":
275	      return minutes > 0 ? `${base}:${minutes}` : base;
276	    case "techie":
277	      return `${sign}${padStart(Math.abs(hours), 2)}${padStart(minutes, 2)}`;
278	    default:
279	      throw new RangeError(`Value format ${format} is out of range for property format`);
280	  }
281	}
282	
283	export function timeObject(obj) {
284	  return pick(obj, ["hour", "minute", "second", "millisecond"]);
285	}
286	
287	export const ianaRegex = /[A-Za-z_+-]{1,256}(:?\/[A-Za-z_+-]{1,256}(\/[A-Za-z_+-]{1,256})?)?/;

