const { DateTime } = require("/luxon/src/luxon");

function daysInMonth(y, m) {
  const mm = ((m - 1) % 12 + 12) % 12 + 1;
  const yy = y + (m - mm) / 12;
  if (mm === 2) return (yy % 4 === 0 && (yy % 100 !== 0 || yy % 400 === 0)) ? 29 : 28;
  return [31, null, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][mm - 1];
}

// reference: normalize the calendar fields in the *target* year
function ref(y, m, d, addMonths, addDays, addYears) {
  const ty = y + addYears, tm = m + addMonths;
  const cappedDay = Math.min(d, daysInMonth(ty, tm)) + addDays;
  const date = new Date(Date.UTC(2000, 0, 1));
  date.setUTCFullYear(ty, tm - 1, cappedDay);
  return date.toISOString().slice(0, 10);
}

let checked = 0, bad = 0;
const months = [0, 1, 2, 3, 11, 12, 13, 14, 23, -1, -2, -12, -13];
const days = [0, 1, 2, 27, 28, 29, 30, 31, 59, 60, 61, 62, 90, 91, 92, 365, 366];
for (let y = 0; y <= 110; y++) {
  for (let m = 1; m <= 12; m++) {
    for (const d of [1, 15, 28, 29, 30, 31]) {
      if (d > daysInMonth(y, m)) continue;
      const iso = `${String(y).padStart(4, "0")}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
      const base = DateTime.fromISO(iso, { zone: "utc" });
      if (!base.isValid) { console.log("invalid base", iso, base.invalidReason); bad++; continue; }
      for (const am of months) {
        for (const ad of [0, 1, 2, 61]) {
          const got = base.plus({ months: am, days: ad }).toISODate();
          const want = ref(y, m, d, am, ad, 0);
          checked++;
          if (got !== want) { bad++; if (bad < 15) console.log("MISMATCH", iso, "+", am, "mo", ad, "d => got", got, "want", want); }
        }
      }
      for (const ad of days) {
        const got = base.plus({ days: ad }).toISODate();
        const want = ref(y, m, d, 0, ad, 0);
        checked++;
        if (got !== want) { bad++; if (bad < 15) console.log("MISMATCH", iso, "+", ad, "d => got", got, "want", want); }
      }
      for (const ay of [1, 2, -1]) {
        const got = base.plus({ years: ay }).toISODate();
        const want = ref(y, m, d, 0, 0, ay);
        checked++;
        if (got !== want) { bad++; if (bad < 15) console.log("MISMATCH", iso, "+", ay, "y => got", got, "want", want); }
      }
    }
  }
}
